1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	const CURSE_SURCHARGE_RATE = 0.5;
27	const HIGH_ENCHANTMENT_THRESHOLD = 5;
28	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_PREMIUM = 60;
41	
42	/** Items that share the same `type`, and so are priced together. */
43	type AlikeItems = Item[];
44	
45	const groupByType = (items: Item[]): AlikeItems[] => {
46	  const itemsByType = new Map<string, Item[]>();
47	  for (const item of items) {
48	    const alike = itemsByType.get(item.type);
49	    if (alike) alike.push(item);
50	    else itemsByType.set(item.type, [item]);
51	  }
52	  return [...itemsByType.values()];
53	};
54	
55	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
56	
57	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
58	
59	const basePremiumFor = (alike: AlikeItems): number =>
60	  formsBlock(alike)
61	    ? BLOCK_PREMIUM
62	    : alike.reduce((total, item) => total + itemBasePremium(item), 0);
63	
64	const totalBasePremium = (items: Item[]): number =>
65	  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);
66	
67	const isCursed = (item: Item): boolean => item.cursed === true;
68	
69	const isHighlyEnchanted = (item: Item): boolean =>
70	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
71	
72	/**
73	 * An item-specific surcharge: `rate` × the item's own base premium, charged
74	 * once per item the rule `applies` to. Never charged on the policy's base, so
75	 * every rule contributes an independent additive term.
76	 */
77	type ItemSurcharge = { applies: (item: Item) => boolean; rate: number };
78	
79	const ITEM_SURCHARGES: ItemSurcharge[] = [
80	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
81	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
82	];
83	
84	const itemSurchargesFor = (item: Item): number =>
85	  ITEM_SURCHARGES.filter(({ applies }) => applies(item)).reduce(
86	    (total, { rate }) => total + itemBasePremium(item) * rate,
87	    0,
88	  );
89	
90	const totalItemSurcharges = (items: Item[]): number =>
91	  items.reduce((total, item) => total + itemSurchargesFor(item), 0);
92	
93	const quotePremium = (items: Item[]): number => {
94	  const base = totalBasePremium(items);
95	  // Keep the surcharge additive (base + base * rate). The algebraically
96	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
97	  // which Math.ceil turns into a premium that is 1 G too high.
98	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
99	  return Math.ceil(
100	    base + totalItemSurcharges(items) + firstInsuranceSurcharge + PROCESSING_FEE,
101	  );
102	};
103	
104	export const runScenario = (scenario: Scenario): Result[] =>
105	  scenario.steps.map((step) => {
106	    if (step.op === "quote") return { premium: quotePremium(step.items) };
107	    throw new Error(`Unsupported step: ${step.op}`);
108	  });
